/*
 * htmx-lite: implementación mínima y autónoma de las funciones de HTMX que
 * usa esta app (hx-get, hx-post, hx-target, hx-swap="innerHTML", hx-trigger
 * con "keyup changed delay:Nms", hx-on::after-request).
 *
 * Se incluye localmente porque el entorno bloquea los CDN. Si en producción
 * prefieres el HTMX oficial, sustituye este archivo por htmx.min.js real
 * (mismos nombres de atributo, es compatible).
 */
(function () {
  "use strict";

  function q(sel, ctx) { return (ctx || document).querySelector(sel); }

  function resolveTarget(el) {
    var t = el.getAttribute("hx-target");
    if (!t) {
      // Por defecto: el propio elemento (o su formulario si es un control).
      return el.form || el;
    }
    if (t === "this") return el;
    return q(t) || el;
  }

  function swap(el, target, html) {
    var mode = el.getAttribute("hx-swap") || "innerHTML";
    if (mode === "outerHTML") {
      target.outerHTML = html;
    } else {
      target.innerHTML = html;
    }
  }

  function runAfter(el) {
    var code = el.getAttribute("hx-on::after-request");
    if (code) {
      try { new Function(code).call(el); } catch (e) { console.error(e); }
    }
  }

  function buildRequest(el) {
    var url = el.getAttribute("hx-get") || el.getAttribute("hx-post");
    var method = el.hasAttribute("hx-post") ? "POST" : "GET";
    var opts = { method: method, headers: { "HX-Request": "true" } };

    if (el.tagName === "FORM") {
      var fd = new FormData(el);
      if (method === "GET") {
        url += (url.indexOf("?") >= 0 ? "&" : "?") + new URLSearchParams(fd).toString();
      } else {
        opts.body = fd;
      }
    } else if (el.name) {
      // Control suelto (p. ej. un input de búsqueda): envía nombre=valor.
      var params = new URLSearchParams();
      params.set(el.name, el.value);
      if (method === "GET") {
        url += (url.indexOf("?") >= 0 ? "&" : "?") + params.toString();
      } else {
        opts.body = params;
      }
    }
    return { url: url, opts: opts };
  }

  function trigger(el) {
    var target = resolveTarget(el);
    var req = buildRequest(el);
    fetch(req.url, req.opts)
      .then(function (r) { return r.text(); })
      .then(function (html) {
        swap(el, target, html);
        runAfter(el);
        bind(target); // vincula el HTML recién insertado
      })
      .catch(function (e) { console.error("htmx-lite:", e); });
  }

  function parseTrigger(el) {
    // Devuelve { event, changed, delay }
    var spec = el.getAttribute("hx-trigger");
    if (!spec) {
      return { event: el.tagName === "FORM" ? "submit" : "click", changed: false, delay: 0 };
    }
    var parts = spec.split(/\s+/);
    var out = { event: parts[0], changed: false, delay: 0 };
    parts.slice(1).forEach(function (p) {
      if (p === "changed") out.changed = true;
      var m = /^delay:(\d+)ms$/.exec(p);
      if (m) out.delay = parseInt(m[1], 10);
    });
    return out;
  }

  function bind(root) {
    var nodes = (root || document).querySelectorAll("[hx-get],[hx-post]");
    nodes.forEach(function (el) {
      if (el.__hxBound) return;
      el.__hxBound = true;
      var t = parseTrigger(el);
      var timer = null;
      var lastValue = el.value;

      el.addEventListener(t.event, function (ev) {
        if (t.event === "submit") ev.preventDefault();
        if (t.changed && el.value === lastValue) return;
        lastValue = el.value;
        if (t.delay) {
          clearTimeout(timer);
          timer = setTimeout(function () { trigger(el); }, t.delay);
        } else {
          trigger(el);
        }
      });
    });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", function () { bind(document); });
  } else {
    bind(document);
  }

  // API mínima para compatibilidad
  window.htmx = { process: bind };
})();
